-- 按最终确认的五大职业类别补齐 50 个职业/题目。
UPDATE gkzh_zycck_category SET code='digital_product',name='数字产品与体验类',draw_mode='fixed',sort_order=1 WHERE code='technology';
UPDATE gkzh_zycck_category SET code='digital_content',name='数字内容与创意类',draw_mode='fixed',sort_order=2 WHERE code='health';
UPDATE gkzh_zycck_category SET code='digital_marketing',name='数字营销与商业类',draw_mode='random',sort_order=3 WHERE code='culture';
UPDATE gkzh_zycck_category SET code='professional_service',name='专业服务与知识服务类',draw_mode='random',sort_order=4 WHERE code='management';
UPDATE gkzh_zycck_category SET code='freelance_skill',name='个人技能与自由职业类',draw_mode='random',sort_order=5 WHERE code='nature';
UPDATE gkzh_zycck_category SET draw_mode='fixed' WHERE code IN ('digital_product','digital_content');
UPDATE gkzh_zycck_category SET draw_mode='random' WHERE code IN ('digital_marketing','professional_service','freelance_skill');
DELETE q FROM gkzh_zycck_career_question q JOIN gkzh_zycck_category c ON c.category_id=q.category_id;
DROP TEMPORARY TABLE IF EXISTS tmp_zycck_final;
CREATE TEMPORARY TABLE tmp_zycck_final(category_code VARCHAR(32),career_name VARCHAR(100),intro VARCHAR(500));
