INSERT INTO gkzh_zycck_career_question(category_id,career_name,one_line_intro,main_work,day_example,why_exists,option_a,option_b,option_c,option_d,option_a_career_id,option_b_career_id,option_c_career_id,option_d_career_id,correct_option_key,explanation,draw_candidate,sort_order,status,create_time,update_time)
SELECT c.category_id,t.career_name,t.intro,t.intro,CONCAT('围绕',t.career_name,'的典型任务开展工作。'),CONCAT('社会需要',t.career_name,'解决真实问题。'),t.career_name,'产品经理','数字营销策划','独立摄影师',0,0,0,0,'A',CONCAT('正确答案对应的职业是：',t.career_name,'。'),'0',1,'0',NOW(),NOW() FROM tmp_zycck_final t JOIN gkzh_zycck_category c ON c.code=t.category_code
ON DUPLICATE KEY UPDATE one_line_intro=VALUES(one_line_intro),main_work=VALUES(main_work),day_example=VALUES(day_example),why_exists=VALUES(why_exists),option_a=VALUES(option_a),option_b=VALUES(option_b),option_c=VALUES(option_c),option_d=VALUES(option_d),correct_option_key='A',explanation=VALUES(explanation),status='0',update_time=NOW();
DROP TEMPORARY TABLE IF EXISTS tmp_zycck_rank;
CREATE TEMPORARY TABLE tmp_zycck_rank AS SELECT q.career_question_id,q.category_id,q.career_name,(SELECT COUNT(*) FROM gkzh_zycck_career_question x WHERE x.category_id=q.category_id AND x.career_question_id<=q.career_question_id) rn FROM gkzh_zycck_career_question q;
CREATE TEMPORARY TABLE tmp_zycck_rank_b AS SELECT * FROM tmp_zycck_rank;
CREATE TEMPORARY TABLE tmp_zycck_rank_c AS SELECT * FROM tmp_zycck_rank;
CREATE TEMPORARY TABLE tmp_zycck_rank_d AS SELECT * FROM tmp_zycck_rank;
UPDATE gkzh_zycck_career_question q JOIN tmp_zycck_rank s ON s.career_question_id=q.career_question_id JOIN tmp_zycck_rank_b b ON b.category_id=s.category_id AND b.rn=IF(s.rn=10,1,s.rn+1) JOIN tmp_zycck_rank_c d ON d.category_id=s.category_id AND d.rn=IF(s.rn>=9,s.rn-8,s.rn+2) JOIN tmp_zycck_rank_d e ON e.category_id=s.category_id AND e.rn=IF(s.rn>=8,s.rn-7,s.rn+3) SET q.option_a_career_id=s.career_question_id,q.option_b_career_id=b.career_question_id,q.option_c_career_id=d.career_question_id,q.option_d_career_id=e.career_question_id,q.option_a=s.career_name,q.option_b=b.career_name,q.option_c=d.career_name,q.option_d=e.career_name,q.sort_order=s.rn;
UPDATE gkzh_zycck_career_question SET draw_candidate='0';
UPDATE gkzh_zycck_career_question q JOIN (SELECT category_id,MIN(career_question_id) id FROM gkzh_zycck_career_question GROUP BY category_id) x ON x.category_id=q.category_id AND x.id=q.career_question_id SET q.draw_candidate='1';
DROP TEMPORARY TABLE IF EXISTS tmp_zycck_random_candidates;
CREATE TEMPORARY TABLE tmp_zycck_random_candidates AS SELECT x.career_question_id FROM gkzh_zycck_career_question x WHERE x.category_id=(SELECT category_id FROM gkzh_zycck_category WHERE code='digital_marketing') AND (SELECT COUNT(*) FROM gkzh_zycck_career_question y WHERE y.category_id=x.category_id AND y.career_question_id<=x.career_question_id)<=3;
UPDATE gkzh_zycck_career_question q JOIN tmp_zycck_random_candidates r ON r.career_question_id=q.career_question_id SET q.draw_candidate='1';
DROP TEMPORARY TABLE IF EXISTS tmp_zycck_random_candidates;
CREATE TEMPORARY TABLE tmp_zycck_random_candidates AS SELECT x.career_question_id FROM gkzh_zycck_career_question x JOIN gkzh_zycck_category c ON c.category_id=x.category_id WHERE c.draw_mode='random' AND (SELECT COUNT(*) FROM gkzh_zycck_career_question y WHERE y.category_id=x.category_id AND y.career_question_id<=x.career_question_id)<=3;
UPDATE gkzh_zycck_career_question q JOIN tmp_zycck_random_candidates r ON r.career_question_id=q.career_question_id SET q.draw_candidate='1';
